29	struct ConversationInfo
30	{
31	    std::string id;
32	    std::string title;
33	    std::string created_at;
34	    std::string updated_at;
35	    std::string preview;
36	    std::uint64_t activity_seq{0};
37	};
38	
39	// One entry of the change log: an edit the workspace reported, stored raw.
40	// The Agent page groups consecutive entries for display; nothing here merges,
41	// words, or delays them, so the grouping can change without touching saved
42	// data.
43	struct ChangeEntry
44	{
45	    std::uint64_t seq{0};
46	    std::string   created_at;
47	    std::string   kind;            // step|undo|redo|setting|preset
48	    std::string   actor;           // person|agent
49	    bool          external{false}; // an agent edit an external tool made, through MCP
50	    std::string   label;           // as the workspace reported it; may be empty
51	    std::string   location;        // optional place of a hand edit, when known
52	    std::string   from, to, preset; // setting only
53	    std::string   key;              // setting only; absent in older documents
54	    std::string   conversation_id; // the conversation active at the time
55	    std::string   after_id;        // the conversation item it follows; empty before the first
56	};
57	
58	// One piece of work the application ran outside the chat: a slice, an arrange,
59	// an export. The entry is written when the work starts, which fixes its place
60	// in the timeline: after the conversation item that was last at that moment,
61	// so a message that arrives later reads below it. It is completed in place
62	// when the work ends. Progress is not saved; an entry still "running" in a
63	// document that was closed mid-run is shown as interrupted.
64	struct WorkEntry
65	{
66	    std::uint64_t seq{0};
67	    std::string   id;
68	    std::string   started_at, ended_at;
69	    std::string   kind;            // slice|job|export|upload|download
70	    std::string   title;           // what is running, in the app's words
71	    std::string   state;           // running|done|cancelled|failed
72	    std::string   detail;          // why it failed; never a folder path
73	    std::string   conversation_id; // the conversation active when it started
74	    std::string   after_id;        // the conversation item it follows; empty before the first
75	};
76	
77	// Metadata for one attachment. The blob lives under
78	// <JusPrin data dir>/attachments/<id>/<stored_name>; this record is the
79	// portable, saved description of it. `state` is "staged" while the attachment
80	// sits in the composer and "sent" once a durable user message owns it.
81	struct AttachmentRecord
82	{
83	    std::string   id;            // "a-<n>", also the blob subdirectory name
84	    std::uint64_t seq{0};
85	    std::string   client_id;     // page-supplied stable ID, for resend dedup
86	    std::string   original_name; // display name as chosen by the user
87	    std::string   stored_name;   // sanitized file name written to disk
88	    std::string   kind;          // text|image|svg|pdf|gcode|model|unsupported
89	    std::string   mime;
90	    std::uint64_t size_bytes{0};
91	    std::string   source;        // picker|drop|clipboard|project
92	    std::string   state;         // staged|sent|error
93	    std::string   preview_text;  // decoded text preview (may be truncated)
94	    std::string   preview_data_url; // small image thumbnail data URL
95	    std::string   summary;       // native, non-binary model summary
96	    std::string   content_hash;  // opaque content hash, when computed
97	    std::optional<AgentError> error;
98	
99	    // Relative (to the JusPrin data dir) directory holding the blob.
100	    std::string relative_dir() const { return "attachments/" + id; }
101	    // Relative path of the blob itself.
102	    std::string relative_path() const { return relative_dir() + "/" + stored_name; }
103	};
104	
105	// Where a recorded fact came from. A tool never promotes an inferred value to
106	// confirmed; only a write of the user's explicit answer does.
107	enum class Provenance : std::uint8_t { File, Observed, AgentInferred, UserConfirmed };
108	
109	// One spelling, shared by the stored document and every tool result.
110	inline const char* provenance_name(Provenance provenance)
111	{
112	    switch (provenance) {
113	    case Provenance::File: return "file";
114	    case Provenance::Observed: return "observed";
115	    case Provenance::UserConfirmed: return "user_confirmed";
116	    case Provenance::AgentInferred: break;
117	    }
118	    return "agent_inferred";
119	}
120	
121	inline Provenance provenance_from(const std::string& text)
122	{
123	    if (text == "file") return Provenance::File;
124	    if (text == "observed") return Provenance::Observed;
125	    if (text == "user_confirmed") return Provenance::UserConfirmed;
126	    return Provenance::AgentInferred;
127	}
128	
129	// One answer in the print intent: what the user wants out of this print,
130	// rather than how to slice it. The field vocabulary belongs to the tool that
131	// writes it and validates what it accepts; the store keeps what was written,
132	// where it came from, and when. This is not a conversation's setup_intent,
133	// which restates one delegation in the user's own words.
134	struct IntentField
135	{
136	    std::string   field;
137	    std::string   value;
138	    // Set when the agent has asked about this field and has no answer yet: the
139	    // question it asked, in the words it used. A field with a question and no
140	    // value is what the agent still does not know, which is the only way to
141	    // have that list when the field names are the agent's own invention.
142	    std::string   question;
143	    Provenance    provenance{Provenance::AgentInferred};
144	    std::uint64_t seq{0};
145	    std::string   updated_at;
146	
147	    bool answered() const { return !value.empty(); }
148	};
149	
150	// One decision the agent made and is prepared to defend.
151	struct PlanDecision
152	{
153	    std::string topic;       // orientation, supports, material, ...
154	    std::string statement;   // the decision and its reasoning, in the user's terms
155	    std::string confidence;  // the agent's own confidence in it
156	    std::string alternative; // what else was considered, and why it lost
157	};
158	
159	// The agent's pinned statement of how it means to print this project: what it
160	// decided, what it assumed without being able to check, and what could still
161	// go wrong. The agent's own words, not a description of the configuration --
162	// the configuration is read from the presets, which cannot say why.
163	struct PlanRecord
164	{
165	    std::uint64_t             seq{0};
166	    std::string               updated_at;
167	    std::string               headline;
168	    std::vector<PlanDecision> decisions;
169	    std::vector<std::string>  assumptions;
170	    std::vector<std::string>  risks;
171	    std::string               validity{"current"};
172	    std::string               invalidated_by;
173	};
