311	    std::vector<Workspace::RegionRecord> set_regions(std::vector<Workspace::RegionRecord> records, const std::string& timestamp);
312	    // Version restore keeps the current conversation and manufacturing audit
313	    // while taking the earlier version's project-specific intent and plan.
314	
315	    // -- Change log -----------------------------------------------------------
316	    // Appends with the next seq, placed in the active conversation after its
317	    // most recent item. Returns the entry as stored.
318	    ChangeEntry              add_change(ChangeEntry entry, const std::string& timestamp);
319	    std::vector<ChangeEntry> changes() const;
