26	const char* message_state_name(MessageState state)
27	{
28	    switch (state) {
29	    case MessageState::Complete: return "complete";
30	    case MessageState::Streaming: return "streaming";
31	    case MessageState::Failed: return "failed";
32	    case MessageState::Stopped: return "stopped";
33	    }
34	    return "complete";
35	}
