37	MessageState message_state_from(const std::string& name)
38	{
39	    if (name == "streaming")
40	        return MessageState::Streaming;
41	    if (name == "failed")
42	        return MessageState::Failed;
43	    if (name == "stopped")
44	        return MessageState::Stopped;
45	    return MessageState::Complete;
46	}
