48	ToolState tool_state_from(const std::string& name)
49	{
50	    if (name == "succeeded")
51	        return ToolState::Succeeded;
52	    if (name == "failed")
53	        return ToolState::Failed;
54	    if (name == "cancelled")
55	        return ToolState::Cancelled;
56	    // Older documents may contain pending, approved, or input_required.
57	    // They are all interrupted work and normalize_interrupted_state cancels them.
