80	// Updates the known fields of an existing JSON object in place, so fields
81	// written by other builds are preserved.
82	void write_message_fields(json& entry, const ConversationMessage& message)
83	{
84	    entry["id"]      = message.id;
85	    entry["role"]    = role_name(message.role);
86	    entry["state"]   = message_state_name(message.state);
87	    entry["text"]    = message.text;
88	    entry["attempt"] = message.attempt;
89	    if (!message.client_message_id.empty())
90	        entry["clientMessageId"] = message.client_message_id;
91	    if (!message.in_reply_to.empty())
92	        entry["inReplyTo"] = message.in_reply_to;
93	    if (message.error)
94	        entry["error"] = json{{"code", message.error->code}, {"message", message.error->message},
95	                              {"retryable", message.error->retryable}};
96	    else
97	        entry.erase("error");
98	    if (!message.attachment_ids.empty())
99	        entry["attachments"] = message.attachment_ids;
100	    else
101	        entry.erase("attachments");
102	    if (!message.swatch.empty())
103	        entry["swatch"] = message.swatch;
104	    else
105	        entry.erase("swatch");
106	    if (!message.file_report.empty()) {
107	        entry["fileReport"]     = message.file_report;
108	        entry["fileReportCard"] = message.file_report_card;
109	    } else {
110	        entry.erase("fileReport");
111	        entry.erase("fileReportCard");
112	    }
113	    if (!message.issue_context.empty())
114	        entry["issueContext"] = message.issue_context;
115	    else
116	        entry.erase("issueContext");
117	}
118	
119	ConversationMessage read_message(const json& entry)
120	{
121	    ConversationMessage message;
122	    message.id                = entry.value("id", "");
123	    message.role              = role_from(entry.value("role", "assistant"));
124	    message.state             = message_state_from(entry.value("state", "complete"));
125	    message.text              = entry.value("text", "");
126	    message.attempt           = entry.value("attempt", 1);
127	    message.client_message_id = entry.value("clientMessageId", "");
128	    message.in_reply_to       = entry.value("inReplyTo", "");
129	    if (entry.contains("error") && entry["error"].is_object())
130	        message.error = AgentError{entry["error"].value("code", ""), entry["error"].value("message", ""),
131	                                   entry["error"].value("retryable", false)};
132	    if (entry.contains("attachments") && entry["attachments"].is_array())
133	        for (const json& id : entry["attachments"])
134	            if (id.is_string())
135	                message.attachment_ids.push_back(id.get<std::string>());
136	    message.swatch           = entry.value("swatch", "");
137	    message.file_report      = entry.value("fileReport", "");
138	    message.file_report_card = entry.value("fileReportCard", false);
139	    message.issue_context    = entry.value("issueContext", "");
140	    return message;
141	}
