143	void write_intent_field(json& entry, const IntentField& field)
144	{
145	    entry["field"]      = field.field;
146	    entry["value"]      = field.value;
147	    entry["provenance"] = provenance_name(field.provenance);
148	    entry["seq"]        = field.seq;
149	    entry["updatedAt"]  = field.updated_at;
150	    if (!field.question.empty())
151	        entry["question"] = field.question;
152	    else
