156	IntentField read_intent_field(const json& entry)
157	{
158	    IntentField field;
159	    field.field       = entry.value("field", "");
160	    field.value       = entry.value("value", "");
161	    field.question    = entry.value("question", "");
162	    field.provenance  = provenance_from(entry.value("provenance", "agent_inferred"));
163	    field.seq         = entry.value("seq", std::uint64_t(0));
164	    field.updated_at  = entry.value("updatedAt", "");
