168	void write_attachment_fields(json& entry, const AttachmentRecord& record)
169	{
170	    entry["id"]           = record.id;
171	    if (!record.client_id.empty())
172	        entry["clientId"] = record.client_id;
173	    entry["originalName"] = record.original_name;
174	    entry["storedName"]   = record.stored_name;
175	    entry["kind"]         = record.kind;
176	    entry["mime"]         = record.mime;
177	    entry["sizeBytes"]    = record.size_bytes;
178	    entry["source"]       = record.source;
179	    entry["state"]        = record.state;
180	    if (!record.preview_text.empty())
181	        entry["previewText"] = record.preview_text;
182	    else
183	        entry.erase("previewText");
184	    if (!record.preview_data_url.empty())
185	        entry["previewDataUrl"] = record.preview_data_url;
186	    else
187	        entry.erase("previewDataUrl");
188	    if (!record.summary.empty())
