368	    }
369	    activity.result_json = entry.value("result", "");
370	    if (entry.contains("error") && entry["error"].is_object())
371	        activity.error = ToolError{entry["error"].value("code", ""), entry["error"].value("message", ""),
372	                                   entry["error"].value("details", json::object()).dump()};
