681	bool ProjectStateDocument::set_setup_intent(const std::string& conversation_id, const std::string& intent)
682	{
683	    json* conversation = conversation_json(conversation_id);
684	    if (!conversation) return false;
685	    const auto first = intent.find_first_not_of(" \t\r\n");
686	    if (first == std::string::npos) return false;
687	    std::string cleaned = intent.substr(first, intent.find_last_not_of(" \t\r\n") - first + 1);
688	    // Keep this a title rather than a paragraph; the card wraps it at narrow
689	    // widths without changing the saved wording.
690	    const auto characters = std::count_if(cleaned.begin(), cleaned.end(), [](unsigned char byte) {
691	        return (byte & 0xc0) != 0x80;
692	    });
693	    if (characters > 120 || cleaned.find_first_of("\r\n") != std::string::npos) return false;
694	    (*conversation)["setupIntent"] = std::move(cleaned);
695	    touch();
696	    return true;
697	}
