1083	std::vector<IntentField> ProjectStateDocument::set_print_intent(const std::vector<IntentField>& fields,
1084	                                                                const std::string&              timestamp)
1085	{
1086	    for (const IntentField& field : fields) {
1087	        if (field.field.empty())
1088	            continue;
1089	        json* stored = nullptr;
1090	        for (json& entry : m_doc["printIntent"])
1091	            if (entry.value("field", "") == field.field)
1092	                stored = &entry;
1093	        if (stored == nullptr) {
1094	            // Ordered by field name so two builds that record the same answers
1095	            // in a different order still write the same document.
1096	            const auto after = std::find_if(m_doc["printIntent"].begin(), m_doc["printIntent"].end(),
1097	                                            [&field](const json& entry) { return entry.value("field", "") > field.field; });
1098	            stored = &*m_doc["printIntent"].insert(after, json::object());
1099	        }
1100	        IntentField written = field;
1101	        written.seq         = next_seq();
1102	        written.updated_at  = timestamp;
1103	        write_intent_field(*stored, written);
1104	    }
1105	    touch();
1106	    return print_intent();
1107	}
