1230	ChangeEntry ProjectStateDocument::add_change(ChangeEntry entry, const std::string& timestamp)
1231	{
1232	    entry.conversation_id = active_conversation_id();
1233	    entry.after_id        = last_item_id(entry.conversation_id);
1234	    entry.seq             = next_seq();
1235	    entry.created_at      = timestamp;
1236	    json record{{"seq", entry.seq},
1237	                {"createdAt", entry.created_at},
1238	                {"kind", entry.kind},
1239	                {"actor", entry.actor},
1240	                {"label", entry.label},
1241	                {"location", entry.location},
1242	                {"conversationId", entry.conversation_id},
1243	                {"afterId", entry.after_id}};
1244	    if (entry.external) record["external"] = true;
1245	    if (entry.kind == "setting") {
1246	        record["from"]   = entry.from;
1247	        record["to"]     = entry.to;
1248	        record["preset"] = entry.preset;
1249	        if (!entry.key.empty()) record["key"] = entry.key;
1250	    } else if (entry.kind == "restore") {
1251	        // Keep the exact source and target versions in the audit entry.
1252	        record["from"] = entry.from;
1253	        record["to"]   = entry.to;
1254	    }
1255	    m_doc["changes"].push_back(std::move(record));
1256	    touch();
1257	    return entry;
1258	}
