1260	WorkEntry ProjectStateDocument::begin_work(WorkEntry entry, const std::string& timestamp)
1261	{
1262	    if (entry.conversation_id.empty()) {
1263	        entry.conversation_id = active_conversation_id();
1264	        entry.after_id        = last_item_id(entry.conversation_id);
1265	    }
1266	    entry.seq             = next_seq();
1267	    entry.id              = "work-" + std::to_string(entry.seq);
1268	    entry.started_at      = timestamp;
1269	    entry.ended_at.clear();
1270	    entry.state           = "running";
1271	    m_doc["work"].push_back(json{{"seq", entry.seq},
1272	                                 {"id", entry.id},
1273	                                 {"startedAt", entry.started_at},
1274	                                 {"endedAt", ""},
1275	                                 {"kind", entry.kind},
1276	                                 {"title", entry.title},
1277	                                 {"state", entry.state},
1278	                                 {"detail", entry.detail},
1279	                                 {"conversationId", entry.conversation_id},
1280	                                 {"afterId", entry.after_id}});
1281	    touch();
1282	    return entry;
1283	}
