1285	std::optional<WorkEntry> ProjectStateDocument::finish_work(const std::string& id, const std::string& state, const std::string& detail,
1286	                                                           const std::string& timestamp)
1287	{
1288	    for (json& entry : m_doc["work"]) {
1289	        if (entry.value("id", "") != id || entry.value("state", "") != "running")
1290	            continue;
1291	        entry["state"]   = state;
1292	        entry["detail"]  = detail;
1293	        entry["endedAt"] = timestamp;
1294	        touch();
1295	        return read_work(entry);
