1316	std::string ProjectStateDocument::last_item_id(const std::string& conversation_id) const
1317	{
1318	    const json* conversation = conversation_json(conversation_id);
1319	    if (conversation == nullptr)
1320	        return {};
1321	    std::string   last_id;
1322	    std::uint64_t last_seq = 0;
1323	    std::set<std::string> message_ids;
1324	    for (const json& message : (*conversation)["messages"]) {
1325	        message_ids.insert(message.value("id", ""));
1326	        if (message.value("seq", std::uint64_t(0)) >= last_seq) {
1327	            last_seq = message.value("seq", std::uint64_t(0));
1328	            last_id  = message.value("id", "");
1329	        }
1330	    }
1331	    // A tool activity belongs to the conversation of the message that
1332	    // started it; one from an external MCP client belongs to none.
1333	    for (const json& activity : m_doc["toolActivities"])
1334	        if (message_ids.count(activity.value("correlationId", "")) != 0 &&
1335	            activity.value("seq", std::uint64_t(0)) >= last_seq) {
1336	            last_seq = activity.value("seq", std::uint64_t(0));
1337	            last_id  = activity.value("actionId", "");
1338	        }
1339	    return last_id;
1340	}
1341	
1342	bool ProjectStateDocument::normalize_interrupted_state()
1343	{
1344	    bool changed = false;
1345	    for (json& conversation : m_doc["conversations"])
1346	        for (json& entry : conversation["messages"])
1347	            if (entry.value("state", "") == "streaming") {
1348	                entry["state"] = "stopped";
1349	                changed        = true;
1350	            }
1351	    for (json& entry : m_doc["toolActivities"]) {
1352	        const ToolState state = tool_state_from(entry.value("state", "running"));
1353	        if (!tool_state_terminal(state)) {
1354	            entry["state"] = "cancelled";
1355	            changed        = true;
1356	        }
1357	    }
1358	    if (changed)
1359	        touch();
1360	    return changed;
1361	}
