36	std::string read_file(const fs::path& path)
37	{
38	    std::ifstream in(path, std::ios::binary);
39	    if (!in.is_open())
40	        return {};
41	    std::stringstream buffer;
42	    buffer << in.rdbuf();
43	    return buffer.str();
44	}
45	
46	bool write_file(const fs::path& path, const std::string& content)
47	{
48	    std::error_code ec;
49	    fs::create_directories(path.parent_path(), ec);
50	    // Write-then-rename keeps a crash from leaving a truncated state file.
51	    const fs::path temp = path.string() + ".tmp";
52	    {
53	        std::ofstream out(temp, std::ios::binary | std::ios::trunc);
54	        if (!out.is_open())
55	            return false;
56	        out << content;
57	        if (!out.good())
58	            return false;
59	    }
60	    fs::rename(temp, path, ec);
61	    return !ec;
62	}
