78	// Shared with each subscription's unsubscribe closure, which outlives neither
79	// the observers nor, through the weak pointer, the persistence that owns them.
80	struct ProjectPersistence::LedgerObservers
81	{
82	    std::uint64_t                                  next_id{1};
83	    std::map<std::uint64_t, std::function<void()>> observers;
84	};
85	
86	Workspace::WorkspaceSubscription ProjectPersistence::subscribe_ledger(std::function<void()> listener)
87	{
88	    const std::uint64_t id = m_ledger_observers->next_id++;
89	    m_ledger_observers->observers.emplace(id, std::move(listener));
90	    std::weak_ptr<LedgerObservers> weak = m_ledger_observers;
91	    return Workspace::WorkspaceSubscription([weak, id]() {
92	        if (auto state = weak.lock())
93	            state->observers.erase(id);
94	    });
95	}
96	
97	void ProjectPersistence::notify_ledger_changed() const
98	{
99	    // Look each observer up just before calling it, so one that unsubscribes
100	    // another, or itself, during dispatch is safe.
101	    std::vector<std::uint64_t> ids;
102	    for (const auto& observer : m_ledger_observers->observers)
103	        ids.push_back(observer.first);
104	    for (const std::uint64_t id : ids) {
105	        const auto found = m_ledger_observers->observers.find(id);
106	        if (found == m_ledger_observers->observers.end())
107	            continue;
108	        const std::function<void()> callback = found->second;
109	        callback();
110	    }
111	}
