113	ProjectPersistence::ProjectPersistence(Workspace::IWorkspace& workspace, Config config)
114	    : m_workspace(workspace), m_config(std::move(config)), m_ledger_observers(std::make_shared<LedgerObservers>())
115	{
116	    if (!m_config.clock)
117	        m_config.clock = default_clock;
118	    if (!m_config.uuid)
119	        m_config.uuid = default_uuid;
120	    if (m_config.in_memory) {
121	        // No project to follow and nowhere to mirror to: this session is its
122	        // own boundary, and it needs an identity now because ids are minted
123	        // from it.
124	        m_config.recovery_root.clear();
125	        m_document.initialize_identity("p-" + m_config.uuid(), "l-" + m_config.uuid(), m_config.clock());
126	        return;
127	    }
128	    m_subscription = m_workspace.subscribe([this](const Workspace::WorkspaceChanged& change) {
129	        on_workspace_changed(change);
130	    });
131	    m_edit_subscription = m_workspace.subscribe_edits([this](const Workspace::WorkspaceEdit& edit) { on_edit(edit); });
132	}
