134	void ProjectPersistence::on_edit(const Workspace::WorkspaceEdit& edit)
135	{
136	    // The edit belongs to whatever project is really open now.
137	    resolve_pending_boundary();
138	    ChangeEntry entry;
139	    entry.kind   = edit_kind_name(edit.kind);
140	    entry.actor    = edit.actor == Workspace::EditActor::Person ? "person" : "agent";
141	    entry.external = edit.actor == Workspace::EditActor::ExternalTool;
142	    entry.label  = edit.label;
143	    entry.from   = edit.before;
144	    entry.to     = edit.after;
145	    entry.preset = edit.preset;
146	    entry.key    = edit.key;
147	    const ChangeEntry stored = m_document.add_change(std::move(entry), m_config.clock());
148	    m_document.mark_plan_needs_reassessment(stored.label.empty() ? "The project changed" : stored.label);
149	    // A paint session is a burst of edits; the owner's pacing timer writes them.
150	    commit();
151	    if (m_change_added)
152	        m_change_added(stored);
153	}
