186	void ProjectPersistence::on_workspace_changed(const Workspace::WorkspaceChanged& change)
187	{
188	    if (m_managed_restore_active)
189	        return;
190	    if (has_reason(change.reasons, WorkspaceChangeReasons::Project)) {
191	        if (!m_attached || m_workspace.auxiliary_data_dir() != m_attached_aux_dir) {
192	            // The new project's directory is already in place: adopt it.
193	            adopt_current_project(/*in_place_reset=*/false);
194	        } else {
195	            // Ambiguous: either an in-place full reset, or a replacement
196	            // whose event was published before the directory moved. Park the
197	            // decision until the directory settles.
198	            m_boundary_pending = true;
199	        }
200	        return;
201	    }
202	    if (heal_if_directory_moved())
203	        return;
204	    if (m_boundary_pending) {
205	        // A later event with the directory still in place means the project
206	        // operation completed without moving it: an in-place reset.
207	        resolve_pending_boundary();
208	    }
209	}
210	
211	bool ProjectPersistence::heal_if_directory_moved()
212	{
213	    // A changed auxiliary directory marks an Orca project boundary. Managed
214	    // state is then adopted from the local store or imported from that
215	    // directory's legacy auxiliary document.
216	    if (!m_attached || m_workspace.auxiliary_data_dir() == m_attached_aux_dir)
217	        return false;
218	    m_boundary_pending = false;
219	    adopt_current_project(/*in_place_reset=*/false);
220	    return true;
221	}
222	
223	void ProjectPersistence::resolve_pending_boundary()
224	{
225	    if (m_managed_restore_active)
226	        return;
227	    if (heal_if_directory_moved())
228	        return;
229	    if (!m_boundary_pending)
230	        return;
231	    m_boundary_pending = false;
232	    adopt_current_project(/*in_place_reset=*/true);
233	}
234	
235	void ProjectPersistence::during_managed_restore(const std::function<void()>& operation)
236	{
237	    if (m_config.managed_root.empty() || m_managed_restore_active)
238	        throw std::logic_error("managed restore requires an open managed project");
239	    m_managed_restore_active = true;
240	    struct RestoreGuard {
241	        bool& active;
242	        ~RestoreGuard() { active = false; }
243	    } guard{m_managed_restore_active};
244	    operation();
245	}
246	
247	void ProjectPersistence::adopt_current_project(bool in_place_reset)
248	{
249	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
250	    m_attached         = true;
251	    m_draft.clear();
252	
253	    if (in_place_reset) {
254	        // A full in-place reset is a new project boundary: earlier state does
255	        // not carry into it.
256	        if (m_config.managed_root.empty()) {
257	            std::error_code ec;
258	            fs::remove_all(jusprin_data_dir(), ec);
259	        }
260	        start_fresh_identity();
261	        return;
262	    }
263	
264	    // An external archive can carry the old auxiliary document. Read it once
265	    // for migration; managed snapshots never write authoritative state there.
266	    const fs::path legacy_state = fs::path(m_attached_aux_dir) / kJusPrinDirName / kStateFileName;
267	    const std::string state_text = read_file(m_config.managed_root.empty() ? fs::path(state_file_path()) : legacy_state);
268	    if (state_text.empty()) {
269	        start_fresh_identity();
270	        return;
271	    }
272	
273	    ProjectStateDocument loaded;
274	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
275	    if (result == ProjectStateDocument::LoadResult::Corrupt) {
276	        // Keep the unreadable file for inspection, then start over.
277	        std::error_code ec;
278	        fs::rename(legacy_state, legacy_state.string() + ".corrupt", ec);
279	        start_fresh_identity();
280	        return;
281	    }
282	    m_document = std::move(loaded);
283	
284	    // The recovery mirror may hold state newer than the last explicit save
285	    // (messages, tool activity, a partial reply from before a crash).
286	    const std::string recovery = m_config.managed_root.empty() ? recovery_dir() :
287	        (m_config.recovery_root.empty() ? std::string() :
288	            (fs::path(m_config.recovery_root) / m_document.project_id()).string());
289	    if (!recovery.empty()) {
290	        const std::string mirror_text = read_file(fs::path(recovery) / kStateFileName);
291	        if (!mirror_text.empty()) {
292	            ProjectStateDocument mirror;
293	            if (mirror.load(mirror_text) != ProjectStateDocument::LoadResult::Corrupt &&
294	                mirror.project_id() == m_document.project_id() && mirror.doc_revision() > m_document.doc_revision())
295	                m_document = std::move(mirror);
296	        }
297	        if (m_config.managed_root.empty())
298	            load_recovery_meta();
299	    }
300	
301	    if (!m_config.managed_root.empty()) {
302	        // A copied or reopened external archive is an import, even when it
303	        // carries an identity that already has a managed head on this host.
304	        if (fs::exists(fs::path(m_config.managed_root) / m_document.project_id() / "HEAD"))
305	            m_document.fork_identity("p-" + m_config.uuid(), m_config.clock());
306	        const fs::path old_attachments = fs::path(m_attached_aux_dir) / kJusPrinDirName / "attachments";
307	        const fs::path local_attachments = fs::path(jusprin_data_dir()) / "attachments";
308	        if (fs::is_directory(old_attachments)) {
309	            for (const auto& entry : fs::recursive_directory_iterator(old_attachments)) {
310	                const fs::path target = local_attachments / fs::relative(entry.path(), old_attachments);
311	                if (entry.is_directory())
312	                    fs::create_directories(target);
313	                else if (entry.is_regular_file()) {
314	                    fs::create_directories(target.parent_path());
315	                    fs::copy_file(entry.path(), target, fs::copy_options::overwrite_existing);
316	                }
317	            }
318	        }
319	    }
320	
321	    // A stream or run interrupted by the crash/restart cannot resume.
322	    m_document.normalize_interrupted_state();
323	    if (!m_config.managed_root.empty()) {
324	        m_draft = m_document.draft();
325	    }
326	
327	    m_dirty = true;
328	    flush();
329	    notify_document_replaced();
330	}
