349	void ProjectPersistence::flush()
350	{
351	    if (m_config.in_memory) {
352	        m_dirty = false;
353	        return;
354	    }
355	    // Never write a stale document across an unresolved project boundary.
356	    resolve_pending_boundary();
357	    if (!m_attached)
358	        return;
359	    if (!m_config.managed_root.empty()) {
360	        // ProjectAutosave publishes the document with a model version or as
361	        // a coalesced current-state write between model edits.
362	        m_dirty = false;
363	        return;
364	    }
365	    write_state_to(jusprin_data_dir());
366	    const std::string recovery = recovery_dir();
367	    if (!recovery.empty()) {
368	        write_state_to(recovery);
369	        write_recovery_meta();
370	    }
371	    m_dirty = false;
372	}
