413	    current.mark_plan_needs_reassessment("An earlier model version was restored");
414	    m_document = std::move(current);
415	    m_draft = m_document.draft();
416	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
417	    m_attached = true;
418	    m_boundary_pending = false;
419	    m_dirty = true;
420	    flush();
421	    notify_document_replaced();
