424	void ProjectPersistence::record_chat_restore(const std::string& current_state,
425	                                              const std::string& from_version,
426	                                              const std::string& selected_version,
427	                                              const nlohmann::json& planning,
428	                                              const std::string& conversation_id)
429	{
430	    if (m_config.managed_root.empty())
431	        throw std::logic_error("chat restore requires a managed project document");
432	    ProjectStateDocument current;
433	    if (current.load(current_state) == ProjectStateDocument::LoadResult::Corrupt || !current.has_identity())
434	        throw std::runtime_error("chat checkpoint is unavailable during restore");
435	    const auto checkpoint = current.chat_checkpoint(conversation_id);
436	    if (!checkpoint || checkpoint->value("versionId", "") != selected_version ||
437	        (*checkpoint)["planning"] != planning)
438	        throw std::runtime_error("chat checkpoint changed during restore");
439	    current.normalize_interrupted_state();
440	    current.restore_planning_snapshot(planning);
441	    if (!current.set_active_conversation(conversation_id) || !current.set_viewed_conversation(conversation_id))
442	        throw std::runtime_error("chat disappeared during restore");
443	    ChangeEntry change;
444	    change.kind = "restore";
445	    change.actor = "person";
446	    change.label = "Restored this chat's saved project setup";
447	    change.from = from_version;
448	    change.to = selected_version;
449	    current.add_change(std::move(change), m_config.clock());
450	    m_document = std::move(current);
451	    m_draft = m_document.draft();
452	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
