// Schema 3 kept one print intent, plan and purpose setup for the project, a
// copy of them in each chat's checkpoint (its "planning", with the region
// annotations), and the setup title in each checkpoint's summary. Schema 4
// keeps each on the chat that owns it. The active chat takes the project's;
// an inactive chat takes what its checkpoint saved when it was left, which
// was its own; an inactive chat with no usable checkpoint never had one
// recorded and starts with none. The checkpoint's region copy goes: regions
// belong with model versions, and a version saved before schema 4 has no
// list of its own, so restoring it keeps the current one.
void move_planning_onto_chats(json& doc)
{
    const std::string active = doc.value("activeConversationId", "");
    for (json& chat : doc["conversations"]) {
        if (!chat.is_object())
            continue;
        json source = json::object();
        json* checkpoint = chat.contains("resumeCheckpoint") && chat["resumeCheckpoint"].is_object() ?
            &chat["resumeCheckpoint"] : nullptr;
        if (chat.value("id", "") == active) {
            source = json{{"printIntent", doc.value("printIntent", json::array())},
                          {"plan", doc.value("plan", json::object())},
                          {"purposeSetup", doc.value("purposeSetup", json::object())}};
        } else if (checkpoint && checkpoint->contains("versionId") && (*checkpoint)["versionId"].is_string() &&
                   !(*checkpoint)["versionId"].get<std::string>().empty() && checkpoint->contains("planning") &&
                   (*checkpoint)["planning"].is_object() && checkpoint->contains("summary") &&
                   (*checkpoint)["summary"].is_object() && checkpoint->contains("boundaryId") &&
                   (*checkpoint)["boundaryId"].is_string()) {
            source = (*checkpoint)["planning"];
        }
        const json intent = source.value("printIntent", json::array());
        chat["printIntent"] = intent.is_array() ? intent : json::array();
        const json plan = source.value("plan", json::object());
        if (plan.is_object() && !plan.empty())
            chat["plan"] = plan;
        const json setup = source.value("purposeSetup", json::object());
        if (setup.is_object() && !setup.empty())
            chat["purposeSetup"] = setup;
        if (checkpoint) {
            checkpoint->erase("planning");
            if (checkpoint->contains("summary") && (*checkpoint)["summary"].is_object())
                for (const char* key : {"setupIntent", "planValidity", "planInvalidatedBy"})
                    (*checkpoint)["summary"].erase(key);
        }
    }
    doc.erase("printIntent");
    doc.erase("plan");
    doc.erase("purposeSetup");
}

