    document.set_plan(plan, kT);

    SECTION("a new chat copies the intent and starts with no plan") {
        const std::string second = document.create_conversation({}, kT);
        CHECK(document.setup_intent(second) == "Load-bearing bracket");
        REQUIRE(document.print_intent().size() == 1);
        CHECK(document.print_intent()[0].value == "final part");
        CHECK(document.plan().headline.empty());
        CHECK(document.plan().seq == 0);

        // The copy is the new chat's own: changing it leaves the first alone.
        purpose.value = "quick fit check";
        document.set_print_intent({purpose}, kT);
        REQUIRE(document.set_setup_intent(second, "Quick fit check"));
        PlanRecord quick;
        quick.headline = "Coarse layers and low infill for a quick fit check";
        document.set_plan(quick, kT);
        CHECK(document.plan(first).headline == "Four walls and gyroid infill for strength");
        CHECK(document.setup_intent(first) == "Load-bearing bracket");

        // Switching the active chat switches the project's intent and plan.
        REQUIRE(document.set_active_conversation(first));
        CHECK(document.print_intent()[0].value == "final part");
        CHECK(document.plan().headline == "Four walls and gyroid infill for strength");
        REQUIRE(document.set_active_conversation(second));
        CHECK(document.print_intent()[0].value == "quick fit check");
        CHECK(document.plan().headline == "Coarse layers and low infill for a quick fit check");

        // Each is stored once, on its chat: nothing at the top of the document.
        const json raw = json::parse(document.dump());
        CHECK_FALSE(raw.contains("printIntent"));
        CHECK_FALSE(raw.contains("plan"));
        CHECK_FALSE(raw.contains("purposeSetup"));
        CHECK(raw["conversations"][0]["plan"]["headline"] == "Four walls and gyroid infill for strength");
        CHECK(raw["conversations"][1]["plan"]["headline"] == "Coarse layers and low infill for a quick fit check");
    }

    SECTION("only the active chat's plan is ever marked") {
        const std::string second = document.create_conversation({}, kT);
        PlanRecord other;
        other.headline = "Fine layers with supports away from visible surfaces";
        document.set_plan(other, kT);
        CHECK(document.mark_plan_needs_reassessment("Sparse infill density"));
        CHECK(document.plan(second).validity == "needs_reassessment");
        CHECK(document.plan(first).validity == "current");
    }

    SECTION("a chat with no plan has nothing to mark") {
        document.create_conversation({}, kT);
        CHECK_FALSE(document.mark_plan_needs_reassessment("Sparse infill density"));
        CHECK(document.plan().validity == "current");
    }

    SECTION("deleting the active chat starts its replacement from its intent, with no plan") {
        const auto removed = document.delete_conversation(first, kT);
        REQUIRE(removed);
        const std::string replacement = document.active_conversation_id();
        REQUIRE(replacement != first);
        CHECK(document.setup_intent(replacement) == "Load-bearing bracket");
        REQUIRE(document.print_intent().size() == 1);
        CHECK(document.print_intent()[0].value == "final part");
        CHECK(document.plan().headline.empty());
    }

    SECTION("deleting an inactive chat leaves the active one's as they are") {
        const std::string second = document.create_conversation({}, kT);
        PlanRecord other;
        other.headline = "Spiral vase with a continuous single wall";
        document.set_plan(other, kT);
        REQUIRE(document.delete_conversation(first, kT));
        CHECK(document.active_conversation_id() == second);
        CHECK(document.plan().headline == "Spiral vase with a continuous single wall");
    }
}

TEST_CASE("a schema-3 document moves its intent and plan onto its chats", "[project-state][schema][intent][plan]")
{
    // The shape schema 3 wrote: the project's intent, plan and purpose setup
    // at the top, a copy in each checkpoint's "planning" with the regions,
    // and the setup title in each checkpoint's summary.
    const json region{{"id", "r-1"}, {"kind", "reinforce"}, {"seq", 7}};
    const json active_plan{{"seq", 30}, {"headline", "Four walls and gyroid infill"}, {"validity", "current"},
                           {"invalidatedBy", ""}, {"decisions", json::array()}};
    const json saved_plan{{"seq", 20}, {"headline", "Coarse layers for a quick fit check"},
                          {"validity", "needs_reassessment"}, {"invalidatedBy", "Wall loops"},
                          {"decisions", json::array()}};
    const json old{
        {"schemaVersion", 3},
        {"project", {{"projectId", "p-3"}, {"lineageId", "l-3"}, {"createdAt", kT}}},
        {"activeConversationId", "c-1"},
        {"viewedConversationId", "c-1"},
        {"conversations", json::array({
            {{"id", "c-1"}, {"title", "Strong"}, {"setupIntent", "Strong bracket"}, {"messages", json::array()},
             {"resumeCheckpoint", {{"versionId", "v-9"}, {"boundaryId", ""}, {"savedAt", kT},
                                   {"summary", {{"setupIntent", "Strong bracket"}, {"planValidity", "current"}}},
                                   {"planning", {{"printIntent", json::array()}, {"plan", json::object()},
                                                 {"regions", json::array()}}}}}},
            {{"id", "c-2"}, {"title", "Quick"}, {"setupIntent", "Quick fit check"}, {"messages", json::array()},
             {"resumeCheckpoint", {{"versionId", "v-4"}, {"boundaryId", "m-3"}, {"savedAt", kT},
                                   {"summary", {{"setupIntent", "Quick fit check"}, {"planValidity", "needs_reassessment"},
                                                {"planInvalidatedBy", "Wall loops"}, {"currency", "EUR"}}},
                                   {"planning", {{"printIntent", json::array({{{"field", "purpose"}, {"value", "fit check"}}})},
                                                 {"plan", saved_plan},
                                                 {"purposeSetup", {{"printerPreset", "X1C"}}},
                                                 {"regions", json::array({region})}}}}}},
            {{"id", "c-3"}, {"title", "Never left right"}, {"setupIntent", "Display piece"}, {"messages", json::array()}},
        })},
        {"printIntent", json::array({{{"field", "purpose"}, {"value", "load-bearing"}}})},
        {"plan", active_plan},
        {"purposeSetup", {{"printerPreset", "X1C"}, {"filamentPreset", "PETG"}}},
        {"regions", json::array({region})}};

    ProjectStateDocument document;
    REQUIRE(document.load(old.dump()) == ProjectStateDocument::LoadResult::Migrated);
    const json raw = json::parse(document.dump());
    CHECK(raw["schemaVersion"] == 4);
    CHECK_FALSE(raw.contains("printIntent"));
    CHECK_FALSE(raw.contains("plan"));
    CHECK_FALSE(raw.contains("purposeSetup"));
    // The regions label the model in the workspace and stay with it.
    CHECK(raw["regions"] == json::array({region}));

    // The active chat takes the project's.
    CHECK(document.print_intent()[0].value == "load-bearing");
    CHECK(document.plan().headline == "Four walls and gyroid infill");
    CHECK(document.purpose_setup() == json{{"printerPreset", "X1C"}, {"filamentPreset", "PETG"}});

    // An inactive chat with a checkpoint takes what it was left with, its
    // plan's validity included.
    const PlanRecord quick = document.plan("c-2");
    CHECK(quick.headline == "Coarse layers for a quick fit check");
    CHECK(quick.validity == "needs_reassessment");
    CHECK(quick.invalidated_by == "Wall loops");
    REQUIRE(document.set_active_conversation("c-2"));
    REQUIRE(document.print_intent().size() == 1);
    CHECK(document.print_intent()[0].value == "fit check");
    CHECK(document.purpose_setup() == json{{"printerPreset", "X1C"}});

    // An inactive chat that was never checkpointed keeps its title and has
    // nothing else recorded.
    REQUIRE(document.set_active_conversation("c-3"));
    CHECK(document.setup_intent("c-3") == "Display piece");
    CHECK(document.print_intent().empty());
    CHECK(document.purpose_setup().empty());
    CHECK(document.plan().headline.empty());

    // The checkpoints keep what only they can hold.
    for (const char* chat : {"c-1", "c-2"}) {
        const auto checkpoint = document.chat_checkpoint(chat);
        REQUIRE(checkpoint);
        CHECK_FALSE(checkpoint->contains("planning"));
        CHECK_FALSE((*checkpoint)["summary"].contains("setupIntent"));
        CHECK_FALSE((*checkpoint)["summary"].contains("planValidity"));
        CHECK_FALSE((*checkpoint)["summary"].contains("planInvalidatedBy"));
    }
    CHECK((*document.chat_checkpoint("c-2"))["versionId"] == "v-4");
    CHECK((*document.chat_checkpoint("c-2"))["boundaryId"] == "m-3");
    CHECK((*document.chat_checkpoint("c-2"))["summary"]["currency"] == "EUR");

    // A second load is no migration and changes nothing.
    ProjectStateDocument reloaded;
    REQUIRE(reloaded.load(document.dump()) == ProjectStateDocument::LoadResult::Loaded);
    CHECK(reloaded.dump() == document.dump());
}

